def solve(items, budget):
    if type(budget) is not int or budget<0: raise ValueError('budget')
    if len({i['id'] for i in items})!=len(items) or any(type(i['tokens']) is not int or i['tokens']<0 or type(i['pinned']) is not bool for i in items): raise ValueError('item')
    chosen={n for n,i in enumerate(items) if i['pinned']}
    used=sum(items[n]['tokens'] for n in chosen)
    if used>budget: raise ValueError('pinned overflow')
    for n in sorted(range(len(items)),key=lambda n:(-items[n]['priority'],n)):
        if n not in chosen and used+items[n]['tokens']<=budget:
            chosen.add(n); used+=items[n]['tokens']
    return [i['id'] for n,i in enumerate(items) if n in chosen]

